-- 0010_products_sku_sequence.up.sql
-- F-01: the internal code (sku) is generated by the DB when the user leaves it
-- empty. A SEQUENCE hands out each number exactly once, even when two products
-- are created at the same time (MAX(sku) + 1 would hand the same one twice).
-- Numbers lost by a failed INSERT leave gaps: harmless, the sku only has to be
-- unique, not consecutive.

CREATE SEQUENCE products_sku_seq;

-- Start after the highest all-digits sku already stored (e.g. an imported
-- catalog), so a generated code never collides with an existing one.
SELECT setval('products_sku_seq',
              COALESCE((SELECT max(sku::numeric) FROM products WHERE sku ~ '^[0-9]{1,18}$'), 0)::bigint + 1,
              false);

-- next_product_sku: "000123". lpad alone would cut longer numbers
-- (lpad('1234567', 6, '0') = '123456'), so the width grows past 6 digits.
-- nextval is called once and reused, so each call consumes a single number.
CREATE FUNCTION next_product_sku() RETURNS VARCHAR(40) LANGUAGE sql VOLATILE AS $$
    SELECT lpad(n::text, greatest(6, length(n::text)), '0')
    FROM nextval('products_sku_seq') AS n
$$;

ALTER SEQUENCE products_sku_seq OWNED BY products.sku;
ALTER TABLE products ALTER COLUMN sku SET DEFAULT next_product_sku();
